// A legacy negative reconstructs the entire module and its original-reference capabilities.
const assert=require('node:assert/strict'),{stream}=require('./ge5_role_stream.cjs'),{mutate,encode}=require('./ge5_role_mutations.cjs'),{coherent}=require('./ge5_static_super_ir_mutations.cjs'),roles=require('./ge5_static_super_legacy_module.cjs'),legacy=require('./ge5_static_super_legacy.cjs');
function run(ts,native,actual,original,options){
 const freshN=()=>stream(ts,native.code,native.raw),freshA=()=>stream(ts,actual.code,actual.raw),check=view=>roles.compare(ts,freshN(),coherent(ts,view),options,original);check(freshA());
 const source=ts.createSourceFile('original.ts',original,99,true),view=freshA(),model=legacy.read(ts,view,source,options,{blue:true}),frame=model.frame,points=new Map(),controls=[];
 const point=(offset,label)=>{if(offset>=0&&offset<actual.code.length&&!points.has(offset))points.set(offset,label);};
 for(const[label,node]of[['whole legacy class binding',frame.root],['original retained class',frame.node],['final legacy decorator call',frame.decorate]]){point(node.getStart(view.source),label+' entry');point(node.end,label+'.end');}
 for(const[name,store]of frame.fields){for(const[label,node]of[['store',store.member],['value',store.value]])if(node){point(node.getStart(view.source),label+' '+name);point(node.end,label+' '+name+'.end');}if(store.value)for(const token of view.tokens(store.value))if([',','[',']'].includes(token.text))point(token.start,'whole legacy delimiter '+token.text);}
 for(const program of model.expressions)for(const effect of program.proof.physicalEffects){point(effect.node.getStart(view.source),'legacy '+effect.kind+' entry');point(effect.node.end,'legacy '+effect.kind+'.end');if(effect.logicalNode){point(effect.logicalNode.getStart(view.source),'legacy logical '+effect.kind+' entry');point(effect.logicalNode.end,'legacy logical '+effect.kind+'.end');}}
 const kinds=new Set();function visit(node){if(!kinds.has(node.kind)){kinds.add(node.kind);point(node.end,'complete legacy '+ts.SyntaxKind[node.kind]+'.end');}ts.forEachChild(node,visit);}visit(frame.root);
 for(const comment of view.comments())point(comment.start+Number(comment.end-comment.start>4)*4,'complete legacy comment owner');
 for(const[offset,label]of points)for(const owner of[null,JSON.stringify(actual.owner(offset))==='[0,0,0]'?[0,0,1]:[0,0,0]]){if(JSON.stringify(actual.owner(offset))===JSON.stringify(owner))continue;const changed=coherent(ts,mutate(ts,freshA(),offset,owner));assert.notDeepEqual(changed.owner(offset),actual.owner(offset),'effective whole legacy map control');assert.throws(()=>check(changed),undefined,label);controls.push({label,offset,owner,kind:'fresh coherent bounded map',rejected:true});}
 const publication=view.comments().find(comment=>comment.text.startsWith('//# sourceMappingURL='));assert(publication);const location=view.source.getLineAndCharacterOfPosition(publication.start+4),segments=view.decoded.segments.map(p=>[...p]),at=segments.findIndex(p=>p[0]>location.line||p[0]===location.line&&p[1]>=location.character);segments.splice(at<0?segments.length:at,0,[location.line,location.character,0,0,0],[location.line,location.character]);assert.throws(()=>check(coherent(ts,stream(ts,view.code,JSON.stringify({...JSON.parse(view.raw),mappings:encode(segments)})))),/ordered unique/,'hidden zero-width legacy grant');controls.push({label:'hidden zero-width legacy grant',rejected:true,kind:'fresh coherent bounded map'});
 for(const[field,value]of[['sourceRoot','../forged/'],['names',['forged']]]){const changed=coherent(ts,stream(ts,view.code,JSON.stringify({...JSON.parse(view.raw),[field]:value})));assert.throws(()=>check(changed),undefined,'complete legacy metadata '+field);controls.push({label:'complete legacy metadata '+field,rejected:true});}
 const literal=view.tokens(frame.root).find(token=>/^\d$/.test(token.text));assert(literal);const replacement=literal.text==='5'?'3':'5',code=view.code.slice(0,literal.start)+replacement+view.code.slice(literal.end);assert.throws(()=>check(stream(ts,code,view.raw)),undefined,'changed whole legacy initializer/algorithm literal');controls.push({label:'changed whole legacy initializer/algorithm literal',rejected:true,kind:'whole emitted AST'});
 const wrong=original.replace(/class C extends Base/,'class C extends Baze');assert.notEqual(wrong,original);assert.throws(()=>roles.compare(ts,freshN(),freshA(),options,wrong),undefined,'wrong complete legacy original heritage');controls.push({label:'wrong complete legacy original heritage',rejected:true,kind:'whole original AST'});
 return{completeModuleRoles:true,controls};
}
module.exports={run};
